/* ================= consejero IA ================= */
let CONS={last:null,loading:false};
function gastosBasicos(){return fijosMes()+cuotasMes('pagar')+subsMes()+S.cfg.categorias.filter(c=>c.grupo==='n'&&!fijoCats().has(c.nombre.toLowerCase())).reduce((a,c)=>a+ +c.tope,0)}
function analizar(d){const ing=ingresoMensual(),fij=fijosMes(),cuo=cuotasMes('pagar'),subs=subsMes(),varr=gastoVariableReal(),libre=ing-fij-cuo-subs-varr,liq=liquidez(),bas=gastosBasicos()||1;
  const valor=+d.valor||0,n=Math.max(1,+d.cuotas||1);let cuota=0,total=valor,intereses=0,ea=0,tasaM=0;
  const enCuotas=d.tipo==='credito'||d.tipo==='prestar'||(d.tipo==='comprar'&&d.forma==='cuotas');
  if(enCuotas){if(d.modoInt==='tasa'){tasaM=+d.tasa||0;cuota=annuity(valor,tasaM/100,n)}else if(d.modoInt==='cuota'){cuota=+d.cuotaV||0;tasaM=rateFromCuota(valor,cuota,n,'mensual')}else cuota=valor/n;total=cuota*n;intereses=Math.max(total-valor,0);ea=Math.pow(1+tasaM/100,12)-1}
  let libreD=libre,ratioD=ing?cuo/ing:0,liqD=liq;
  if(d.tipo==='fijo')libreD=libre-valor;else if(d.tipo==='prestar'){liqD=liq-valor}else if(enCuotas){libreD=libre-cuota;ratioD=ing?(cuo+cuota)/ing:0}else liqD=liq-valor;
  const emergA=liq/bas,emergD=liqD/bas;
  let hist=null;if(d.tipo==='prestar'&&d.contactoId){const Ls=S.cobrar.filter(L=>L.contactoId===d.contactoId);hist={n:Ls.length,mora:Ls.filter(L=>engine(L).mora>0).length,saldo:Ls.reduce((a,L)=>a+engine(L).saldo,0),nombre:S.contactos.find(c=>c.id===d.contactoId)?.nombre}}
  const R=[];let v='si';const LIM={prudente:[.25,.35,4,.15],equilibrado:[.3,.4,3,.1],flexible:[.35,.5,2,.05]}[S.cfg.estricto]||[.3,.4,3,.1];const worse=x=>{if(x==='no'||(x==='cuidado'&&v==='si'))v=x};
  if(libreD<0){worse('no');R.push(`Después de esto te faltarían ${$(-libreD)} cada mes para cubrir tus gastos.`)}else if(libreD<ing*LIM[3]){worse('cuidado');R.push(`Te quedarían solo ${$(libreD)} libres al mes.`)}else R.push(`Te seguirían quedando ${$(libreD)} libres al mes.`);
  if(enCuotas&&d.tipo!=='prestar'){if(ratioD>LIM[1]){worse('no');R.push(`Tus deudas se llevarían el ${pct(ratioD,0)} de tu ingreso (lo sano es menos del ${pct(LIM[0],0)}).`)}else if(ratioD>LIM[0]){worse('cuidado');R.push(`Tus deudas pasarían al ${pct(ratioD,0)} de tu ingreso, por encima del ${pct(LIM[0],0)} recomendado.`)}}
  if(d.tipo==='prestar'||(!enCuotas&&d.tipo!=='fijo')){if(liqD<0){worse('no');R.push(`No tienes ${$(valor)} disponibles: te faltan ${$(-liqD)}.`)}else if(emergD<1){worse('no');R.push(`Te quedarías con menos de un mes de colchón para emergencias.`)}else if(emergD<LIM[2]){worse('cuidado');R.push(`Tu colchón para emergencias bajaría de ${emergA.toFixed(1)} a ${emergD.toFixed(1)} meses.`)}}
  if(enCuotas&&ea*100>S.cfg.usura){worse('cuidado');R.push(`El interés equivale a ${pct(ea,1)} anual, por encima de la tasa de usura que tienes configurada (${S.cfg.usura}%).`)}
  if(hist&&hist.mora){worse('cuidado');R.push(`${esc(hist.nombre)} tiene ${hist.mora} préstamo(s) con pagos atrasados.`)}
  if(enCuotas&&intereses>0)R.push(`Pagarías ${$(intereses)} en intereses (en total ${$(total)}).`);
  const dias=ing?valor/(ing/30):0;
  return{v,R,m:{ing,libre,libreD,ratioD,liq,liqD,emergA,emergD,cuota,total,intereses,ea,n,dias,valor,enCuotas,hist,varr,fij,cuo,subs}}}
async function askAI(d,an){let sample=null;if(S.cfg.ia.consejero===false)return{err:'no'};try{sample=window.claude&&window.claude.use?await window.claude.use('sample'):null}catch(e){}if(!sample)return{err:'no'};
  const m=an.m;const ctx={pregunta:{tipo:{comprar:'comprar algo',prestar:'prestarle dinero a alguien',credito:'sacar un crédito',fijo:'asumir un nuevo gasto mensual'}[d.tipo],descripcion:d.desc,valor:m.valor,forma_pago:m.enCuotas?`${m.n} cuotas mensuales de ${Math.round(m.cuota)}`:'de contado',intereses_totales:Math.round(m.intereses),tasa_efectiva_anual_pct:+(m.ea*100).toFixed(1)},
    finanzas:{ingreso_mensual:Math.round(m.ing),gastos_fijos_mes:Math.round(m.fij),cuotas_deudas_mes:Math.round(m.cuo),suscripciones_mes:Math.round(m.subs),gasto_variable_promedio_mes:Math.round(m.varr),dinero_libre_mes_antes:Math.round(m.libre),dinero_libre_mes_despues:Math.round(m.libreD),deudas_sobre_ingreso_despues_pct:+(m.ratioD*100).toFixed(1),disponible_hoy:Math.round(m.liq),disponible_despues:Math.round(m.liqD),meses_colchon_antes:+m.emergA.toFixed(1),meses_colchon_despues:+m.emergD.toFixed(1),metas:S.metas.map(x=>({nombre:x.nombre,falta:Math.round(x.objetivo-x.ahorrado),fecha:x.fecha})),perfil_riesgo:S.perfil.riesgo,tasa_usura_pct:S.cfg.usura},
    historial_del_deudor:m.hist,veredicto_reglas:an.v,observaciones_reglas:an.R};
  const prompt=`Eres un consejero financiero para familias colombianas. Hablas con alguien que NO sabe de finanzas: usa español sencillo de Colombia, frases cortas, sin tecnicismos (si usas uno, explícalo entre paréntesis). Las cifras están en pesos colombianos (COP).
La persona quiere saber si debe hacer esto antes de gastar o prestar. Analiza sus datos reales y responde SOLO con un objeto JSON válido, sin texto adicional, con esta forma exacta:
{"veredicto":"si"|"con_cuidado"|"no","titular":"máximo 12 palabras","explicacion":"2 o 3 frases claras","razones":["3 a 5 razones concretas con cifras en formato $ 1.234.567"],"alternativas":["2 a 4 alternativas prácticas"],"plan":["3 pasos concretos si decide hacerlo"],"pregunta":"una pregunta para que reflexione antes de decidir"}
Sé honesto: si no le conviene, dilo con amabilidad. Respeta el veredicto de las reglas salvo que tengas una razón clara, y explícala. No inventes datos que no estén aquí.
DATOS:
${JSON.stringify(ctx)}`;
  try{const r=await sample.json(prompt,{modelTier:'default'});if(r&&r.veredicto)return{ai:r};return{err:'formato'}}catch(e){return{err:e&&e.code||'error'}}}
V.consejero=()=>{const r=CONS.last,F=CONS.d||{tipo:'comprar',forma:'contado',modoInt:'no',cuotas:12};const tipos=[{v:'comprar',l:'Comprar algo',iso:'tarjetas',d:'Un celular, un viaje, muebles…'},{v:'prestar',l:'Prestar dinero',iso:'me-deben',d:'A un familiar, amigo o cliente'},{v:'credito',l:'Sacar un crédito',iso:'le-debo',d:'Préstamo de banco o libranza'},{v:'fijo',l:'Un nuevo gasto mensual',iso:'suscripciones',d:'Arriendo, plan, gimnasio, colegio'}];
  return pageH('sparkles','b-grad','Consejero antes de gastar','Cuéntame qué piensas hacer. Reviso tus ingresos, gastos, deudas y ahorros, y te digo con palabras sencillas si te alcanza.')+`
  <section class="grid g21"><div class="card ai-card"><form id="consForm" data-form="consejo" class="step">
    <div class="step-h"><span class="n">1</span>¿Qué quieres hacer?</div><div class="choices">${pick('tipo',tipos,F.tipo)}</div>${hidden('tipo',F.tipo)}${hidden('forma',F.forma)}${hidden('modoInt',F.modoInt)}
    <div class="step-h"><span class="n">2</span>Cuéntame los detalles</div>
    <div class="form">${field('¿Qué es?',txt('desc',F.desc||'',{ph:'Ej. Nevera nueva, préstamo a mi primo…',req:true}),{cls:'s2'})}${field('¿Cuánto cuesta?',money('valor',F.valor||'',{req:true}),{hint:'Para un gasto mensual, escribe cuánto es al mes.'})}
    ${field('¿A quién?',S.contactos.length?sel('contactoId',contactOpts(),F.contactoId||'',{ph:'Elige un contacto (opcional)',search:true}):'<span class="note">Agrega contactos para revisar si te han pagado a tiempo.</span>',{show:'tipo:prestar'})}</div>
    <div class="f" data-show="tipo:comprar"><span class="fl">¿Cómo lo pagarías?</span><div class="seg">${pick('forma',[{v:'contado',l:'De contado',icon:'banknote'},{v:'cuotas',l:'A cuotas',icon:'credit-card'}],F.forma,'')}</div></div>
    <div data-show="forma:cuotas" class="step"><div class="form">${field('¿En cuántas cuotas?',num('cuotas',F.cuotas||12),{hint:'Una cuota por mes'})}</div><div class="f"><span class="fl">¿Tiene intereses?</span><div class="seg">${pick('modoInt',[{v:'no',l:'Sin intereses'},{v:'tasa',l:'Sé el porcentaje'},{v:'cuota',l:'Sé el valor de la cuota'}],F.modoInt,'')}</div></div>
      <div class="form">${field('Interés mensual (%)',num('tasa',F.tasa||'',{ph:'Ej. 2'}),{show:'modoInt:tasa',hint:'Si te dicen "al 2%", escribe 2. Las tarjetas suelen cobrar entre 1,8% y 2,2% mensual.'})}${field('Valor de cada cuota',money('cuotaV',F.cuotaV||''),{show:'modoInt:cuota'})}</div></div>
    <button class="btn ai lg" ${CONS.loading?'disabled':''}>${ic('wand-sparkles')}${CONS.loading?'Analizando…':'Analizar con IA'}</button></form></div>
  <div class="grid" style="align-content:start">${CONS.loading?`<div class="card ai-card"><div class="step-h" style="color:#3F7A1E">${ic('sparkles')}Revisando tus finanzas…</div><div class="skel" style="width:70%"></div><div class="skel"></div><div class="skel" style="width:85%"></div><div class="skel" style="width:60%"></div></div>`:r?consResult(r):`<div class="card">${empty('message-circle-question','Aquí verás mi recomendación. Para darte un mejor consejo, mantén al día tus ingresos, gastos fijos y deudas.')}</div>`}
    ${S.consejos.length?`<div class="card"><h2>Consultas anteriores</h2><div class="list">${S.consejos.slice(0,8).map(c=>`<div class="rowi" style="cursor:pointer" data-act="consShow" data-id="${c.id}"><span class="ri ${c.v==='si'?'t-green':c.v==='no'?'t-red':'t-amber'}">${ic(c.v==='si'?'thumbs-up':c.v==='no'?'thumbs-down':'triangle-alert')}</span><div class="rb"><div class="rt">${esc(c.d.desc)}</div><div class="rs">${fdate(parse(c.fecha))} · ${$(c.d.valor)}</div></div></div>`).join('')}</div></div>`:''}</div></section>`};
function consResult(c){const a=c.ai||{},v=a.veredicto==='no'||(!a.veredicto&&c.v==='no')?'no':a.veredicto==='si'||(!a.veredicto&&c.v==='si')?'si':'cuidado';const m=c.m;
  return `<div class="card"><div class="verdict ${v}"><span class="vi">${ic(v==='si'?'thumbs-up':v==='no'?'thumbs-down':'triangle-alert')}</span><div><div class="lbl-s">${v==='si'?'Te alcanza':v==='no'?'Mejor no, por ahora':'Puedes, pero con cuidado'}</div><h2>${esc(a.titular||(v==='si'?'Puedes hacerlo sin poner en riesgo tus finanzas':v==='no'?'Esto pondría en aprietos tus finanzas':'Es posible, pero te deja con poco margen'))}</h2></div></div>
    ${a.explicacion?`<p style="margin:0;font-size:15px;line-height:1.45">${esc(a.explicacion)}</p>`:''}
    <div class="grid g2" style="gap:8px">${m.enCuotas?`<div class="metric"><b>${$(m.cuota)}</b><span>Cuota mensual (${m.n})</span></div><div class="metric"><b>${$(m.intereses)}</b><span>Intereses en total</span></div>`:`<div class="metric"><b>${Math.round(m.dias)} días</b><span>De trabajo que equivale</span></div><div class="metric"><b>${$(m.liqD)}</b><span>Te quedaría disponible</span></div>`}<div class="metric"><b class="${m.libreD<0?'neg':''}">${$(m.libreD)}</b><span>Libre al mes después</span></div><div class="metric"><b>${m.emergD.toFixed(1)} meses</b><span>Colchón de emergencia</span></div></div>
    <h3>Por qué</h3><ul class="clean">${(a.razones||c.R).map(x=>`<li>${esc(String(x).replace(/<[^>]+>/g,''))}</li>`).join('')}</ul>
    ${a.alternativas?`<h3>Otras opciones</h3><ul class="clean">${a.alternativas.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}
    ${a.plan?`<h3>Si decides hacerlo</h3><ul class="clean">${a.plan.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}
    ${a.pregunta?alertBox('info','message-circle-question','Piénsalo',esc(a.pregunta)):''}
    ${c.aiErr?`<p class="note">${ic('info')} No pude consultar la IA en esta vista, así que ves el análisis automático con tus números.</p>`:`<p class="note">${ic('sparkles')} Análisis con IA basado en tus datos. Es una orientación, no reemplaza a un asesor financiero.</p>`}
    ${c.d.tipo==='prestar'&&v!=='no'?`<button class="btn soft" data-modal="loan" data-kind="cobrar" data-cid="${c.d.contactoId||''}" data-monto="${c.d.valor}">${ic('hand-coins')}Registrar este préstamo</button>`:''}</div>`}

