const loanDefaults=(kind,ds)=>({quien:kind==='cobrar'?(ds.cid||S.contactos.length?'ex':'new'):'ent'});
M.gasto=(ds={})=>({t:'Registrar gasto',b:`<form id="mform" data-form="gasto" class="form">${hidden('hormigaMode','auto')}<div class="full" style="display:flex;gap:8px;flex-wrap:wrap"><label class="btn soft" for="fotoFact">${ic('camera')}Leer una factura con foto</label><input id="fotoFact" type="file" accept="image/*" capture="environment" hidden><span class="note" id="fotoHint" style="align-self:center">La IA saca el valor, el comercio y la fecha.</span></div>${field('¿En qué gastaste?',txt('desc',ds.desc||'',{req:true,ph:'Ej. Tinto en la oficina',attrs:'autofocus data-autocat'}),{cls:'full',hint:'Escribe el nombre y la categoría se pone sola.'})}${field('¿Cuánto?',money('valor',ds.valor||'',{req:true}))}${field('Categoría',sel('cat',catOpts(),ds.cat||S.cfg.def.cat||'',{create:1,req:true,search:true,ph:'Se elige sola al escribir'}),{hint:'<span id="catHint"></span>'})}<div class="f full"><span class="fl">¿Es gasto hormiga?</span><div class="seg">${pick('hormigaMode',[{v:'auto',l:'Que lo decida la IA',icon:'sparkles'},{v:'si',l:'Sí',icon:'coffee'},{v:'no',l:'No'}],'auto','')}</div><span class="hint" id="hHint"></span></div>${field('Fecha',datep('fecha',ds.fecha||iso(today())))}${field('¿Quién gastó?',sel('quien',quienOpts(),S.cfg.def.quien||'familia'))}${field('¿Cómo pagaste?',sel('medio',medioOpts(),S.cfg.def.medio||S.cfg.medios[0]?.nombre||''))}${imprevBox()}</form>`,f:`<button class="btn" data-act="mclose">Cancelar</button><button class="btn pri" form="mform">${ic('check')}Guardar gasto</button>`});
const contactFields=(c={},p='')=>`${field('Nombre completo',txt(p+'nombre',c.nombre,{req:!p,ph:'Ej. Andrés Navarro'}),{cls:'s2'})}${field('Tipo de documento',sel(p+'docTipo',[{v:'CC',l:'Cédula de ciudadanía'},{v:'CE',l:'Cédula de extranjería'},{v:'NIT',l:'NIT (empresa)'},{v:'PA',l:'Pasaporte'},{v:'TI',l:'Tarjeta de identidad'}],c.docTipo||'CC'))}${field('Número de documento',txt(p+'doc',c.doc,{attrs:'inputmode="numeric"'}))}${field('Celular o teléfono',txt(p+'telefono',c.telefono,{type:'tel',ph:'300 123 4567'}))}${field('Correo',txt(p+'email',c.email,{type:'email',ph:'nombre@correo.com'}))}${addrFields(p,c)}${field('Relación',sel(p+'relacion',S.cfg.relaciones.map(r=>({v:r,l:r})),c.relacion||'',{ph:'¿Quién es?'}))}`;
M.contacto=ds=>{const c=S.contactos.find(x=>x.id===ds.id)||{};return{t:c.id?'Editar contacto':'Nuevo contacto',b:`<form id="mform" data-form="contacto" data-id="${c.id||''}" class="step">${hidden('tipo',c.tipo||'persona')}<div class="seg">${pick('tipo',[{v:'persona',l:'Persona',icon:'user-round'},{v:'empresa',l:'Empresa',icon:'building-2'}],c.tipo||'persona','')}</div><div class="form">${contactFields(c)}${field('Notas',`<textarea class="inp" name="notas" style="font-family:inherit;font-size:14px;min-height:70px">${esc(c.notas||'')}</textarea>`,{cls:'full'})}</div></form>`,f:`<button class="btn" data-act="mclose">Cancelar</button><button class="btn pri" form="mform">${ic('check')}Guardar</button>`}};
