/* ================= nube y persistencia ================= */
let S=null;const SYNC={cls:'local',t:'Solo en este navegador',s:'Conectando con la nube…'};
const CLOUD={db:null,canWrite:true,estadoExists:false,lastEst:'',lastMonths:{},timer:null,writing:false,again:false,dirty:false,pend:false,gastosSnap:null};
function setSync(cls,t,s){SYNC.cls=cls;SYNC.t=t;SYNC.s=s;const p=document.getElementById('syncP'),q=document.getElementById('syncS');if(p){p.className='syncp '+cls;p.textContent=t}if(q)q.textContent=s}
function commit(){store.set(LKEY(),S);scheduleCloud()}
function scheduleCloud(){CLOUD.deleted=false;if(!CLOUD.db||!CLOUD.canWrite||S.sample)return;CLOUD.dirty=true;CLOUD.pend=true;clearTimeout(CLOUD.timer);CLOUD.timer=setTimeout(flushCloud,700)}
async function flushCloud(){if(CLOUD.writing){CLOUD.again=true;return}CLOUD.writing=true;CLOUD.pend=false;setSync('cloud','Sincronizando…','Guardando cambios');
  try{const est=clone(S);delete est.gastos;const j=JSON.stringify(est);if(j!==CLOUD.lastEst){await CLOUD.db.doc(P_EST()).set({...est,updatedAt:Date.now()});CLOUD.lastEst=j;CLOUD.estadoExists=true}
    const by={};S.gastos.forEach(g=>{const k=g.fecha.slice(0,7);(by[k]=by[k]||[]).push(g)});for(const k of new Set([...Object.keys(by),...Object.keys(CLOUD.lastMonths)])){const jj=JSON.stringify(by[k]||[]);if(jj===CLOUD.lastMonths[k])continue;if(by[k]&&by[k].length){await CLOUD.db.doc(P_G()+'/'+k).set({items:by[k]});CLOUD.lastMonths[k]=jj}else{await CLOUD.db.doc(P_G()+'/'+k).delete();delete CLOUD.lastMonths[k]}}
    setSync('cloud','Guardado en la nube','Se sincroniza con quienes compartas el libro.')}
  catch(e){if(/permission|not_granted|forbidden/i.test((e&&e.code||'')+(e&&e.message||''))){CLOUD.canWrite=false;setSync('err','Solo lectura','No tienes permiso para editar. Tus cambios quedan en este navegador.')}else setSync('err','Sin sincronizar','No se pudo guardar en la nube. Se reintentará con el próximo cambio.')}
  CLOUD.writing=false;if(CLOUD.again){CLOUD.again=false;flushCloud()}else CLOUD.dirty=!!CLOUD.pend}
let pendingRender=false;
const typing=()=>{const a=document.activeElement;return a&&a.closest&&a.closest('main,#modal')&&/INPUT|TEXTAREA/.test(a.tagName)&&a.type!=='hidden'&&a.type!=='checkbox'};
function softRender(){if(typing()||MODAL){pendingRender=true;return}render()}
document.addEventListener('focusout',()=>setTimeout(()=>{if(!pendingRender||typing()||MODAL)return;pendingRender=false;render()},80));
function applyCloud(){if(!CLOUD.estadoExists)return;if(CLOUD.gastosSnap)S.gastos=CLOUD.gastosSnap;store.set(LKEY(),S);softRender()}
async function bootCloud(){let db=null;try{db=window.claude&&window.claude.use?await window.claude.use('db'):null}catch(e){}
  if(!db){setSync('local','Solo en este navegador','La nube no está disponible en esta vista. Exporta respaldos desde Ajustes.');return}
  CLOUD.db=db;let loaded=false;const to=setTimeout(()=>{if(!loaded)setSync('err','Sin conexión','No se pudo leer la nube todavía. Trabajas con la copia local.')},10000);
  db.doc(P_EST()).onSnapshot(snap=>{if(!snap.metadata.fromCache){loaded=true;clearTimeout(to)}
    if(snap.exists){if(snap.metadata.hasPendingWrites||CLOUD.dirty||CLOUD.writing)return;const data=clone(snap.data());delete data.updatedAt;const j=JSON.stringify(data);CLOUD.estadoExists=true;
      if(j!==CLOUD.lastEst){CLOUD.lastEst=j;const g=S.gastos;S=normalize({...data,gastos:g});if(data.v!==3){CLOUD.lastEst='';scheduleCloud()}applyCloud();maybePopups()}
      setSync('cloud','Guardado en la nube','Se sincroniza con quienes compartas el libro.')}
    else if(!snap.metadata.fromCache){CLOUD.estadoExists=false;if(CLOUD.deleted)setSync('local','Cuenta eliminada','Tus datos se borraron. Empieza de nuevo cuando quieras.');else if(S.sample)setSync('local','Ejemplo sin guardar','Empieza tu libro para guardarlo en la nube.');else{flushCloud()}}
  },()=>{clearTimeout(to);setSync('err','Sin conexión','La nube no respondió. Trabajas con la copia local.')});
  db.collection(P_G()).onSnapshot(qs=>{if((qs.metadata&&qs.metadata.hasPendingWrites)||CLOUD.dirty||CLOUD.writing)return;const items=[];qs.docs.forEach(d=>{const b=d.data();CLOUD.lastMonths[d.id]=JSON.stringify(b.items||[]);(b.items||[]).forEach(x=>items.push({...x}))});CLOUD.gastosSnap=items.map(x=>({...x,quien:x.quien||'familia'}));applyCloud()},()=>{})}

/* ================= descargas y PDF ================= */
async function downloadFile(filename,data){let dl=null;try{dl=window.claude&&window.claude.use?await window.claude.use('downloads'):null}catch(e){}
  if(!dl){toast('La descarga no está disponible en esta vista. Abre el libro en claude.ai.');return}
  try{await dl.save({filename,data});toast('Archivo listo')}catch(e){toast(e&&e.code==='declined'?'Descarga cancelada':'No se pudo descargar el archivo.')}}
function buildPDF(k){const J=window.jspdf&&window.jspdf.jsPDF;if(!J){toast('El generador de PDF no cargó. Revisa tu conexión.');return null}
  const R=reportData(k),[yy,mm]=k.split('-').map(Number),doc=new J({unit:'pt',format:'letter'});const W=612,L=48;let y=0;const t=(s,x,yy2,o)=>doc.text(String(s).replace(/[^\x00-\xFF]/g,''),x,yy2,o);
  doc.setFillColor(31,43,75);doc.rect(0,0,W,86,'F');doc.setFillColor(158,219,78);doc.rect(0,86,W,5,'F');doc.setTextColor(255);doc.setFont('helvetica','bold');doc.setFontSize(20);t('Mirai Finanzas',L,44);doc.setFont('helvetica','normal');doc.setFontSize(10.5);t(`Reporte de ${MESL[mm-1]} ${yy}${S.perfil.nombre?' · '+S.perfil.nombre:''} · ${fdate(today())}`,L,64);y=122;doc.setTextColor(20);
  const sec=s=>{if(y>700){doc.addPage();y=56}doc.setFont('helvetica','bold');doc.setFontSize(12.5);doc.setTextColor(63,122,30);t(s,L,y);y+=8;doc.setDrawColor(210);doc.line(L,y,W-L,y);y+=16;doc.setTextColor(20);doc.setFont('helvetica','normal');doc.setFontSize(10)};
  const row=(a,b,bold)=>{if(y>740){doc.addPage();y=56}doc.setFont('helvetica',bold?'bold':'normal');t(a,L,y);t(b,W-L,y,{align:'right'});y+=15};
  sec('Lo que tengo y lo que debo');S.activos.forEach(a=>row(a.nombre,$(conv(a.valor,a.moneda))));row('Inversiones',$(R.T.xi));row('Lo que me deben',$(R.T.xc));row('Total activos',$(R.T.A),1);y+=4;S.pasivos.forEach(a=>row(a.nombre,$(conv(a.valor,a.moneda))));row('Créditos y préstamos',$(R.T.xp));row('Total pasivos',$(R.T.P),1);row('Patrimonio',$(R.T.pat),1);y+=10;
  sec('Resultado del mes');row('Ingresos',$(R.ing));row('Necesidades',$(R.grp.n));row('Gustos',$(R.grp.g));row('Otros gastos',$(R.grp.x+R.grp.a));row('Cuotas de créditos',$(R.cuo));row('Suscripciones',$(R.sub));row(R.res>=0?'Te sobró':'Te faltó',$(R.res),1);y+=10;
  sec('Salud financiera');indicadores().filter(i=>i.ok).forEach(i=>row(i.k.replace(/[¿?]/g,''),`${i.v} · ${i.st==='ok'?'Sano':i.st==='warn'?'Vigilar':'En riesgo'}`));y+=10;
  sec('Préstamos');S.cobrar.forEach(L0=>{const e=engine(L0);row(`Me debe · ${loanName(L0,'cobrar')}`,$(e.saldo))});S.pagar.forEach(L0=>{const e=engine(L0);row(`Le debo · ${loanName(L0,'pagar')}`,$(e.saldo))});y+=10;
  sec('Gastos por categoría');R.cats.forEach(([c,v])=>row(c,$(v)));return doc.output('arraybuffer')}

