function notifToast(n){const box=document.getElementById('toasts');const el=document.createElement('div');el.className='toast';el.innerHTML=`<span class="ni ${n.bg}">${ic(n.icon)}</span><a class="tb" href="#${n.go}" data-nid="${esc(n.id)}" style="color:inherit;text-decoration:none"><b>${esc(n.t)}</b>${esc(n.b)}</a><button class="btn icon sm ghost" aria-label="Cerrar" data-act="tclose">${ic('x')}</button>`;box.appendChild(el);setTimeout(()=>el.remove(),9000)}
